Here's a simple C++ application that reads a directory's contents and outputs file information (name, size) as a CSV file. This code uses the `std::filesystem` library introduced in C++17.

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <filesystem>

namespace fs = std::filesystem;

void write_csv(const std::string& output_file, const fs::path& dir_path) {
    std::ofstream csv_file(output_file);

    if (!csv_file.is_open()) {
        std::cerr << "Error: Could not open output file." << std::endl;
        return;
    }

    // Write header
    csv_file << "File Name,File Size\n";

    try {
        for (const auto& entry : fs::directory_iterator(dir_path)) {
            if (entry.is_regular_file()) {
                csv_file << entry.path().filename().string() << ","
                         << entry.file_size() << "\n";
            }
        }
    } catch (const fs::filesystem_error& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    csv_file.close();
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cout << "Usage: " << argv[0] << " [output.csv] [directory]" << std::endl;
        return 1;
    }

    std::string output_file = argv[1];
    fs::path dir_path(argv[2]);

    if (!fs::exists(dir_path) || !fs::is_directory(dir_path)) {
        std::cerr << "Error: Invalid directory path." << std::endl;
        return 1;
    }

    write_csv(output_file, dir_path);
    std::cout << "CSV file created successfully!" << std::endl;

    return 0;
}
```

To compile and run this code, you need a C++17 compatible compiler. For example, using `g++`:

```bash
$ g++ -std=c++17 main.cpp -o dir_to_csv
$ ./dir_to_csv output.csv /path/to/directory
```

This will create a CSV file named `output.csv` containing the names and sizes of all files in the specified directory.

