```python
def custom_function(t1, t2):
    import numpy as np
    def to_tuple(data):
        if isinstance(data, dict):
            return tuple(data.values())
        elif isinstance(data, list):
            return tuple(data)
        elif isinstance(data, tuple):
            return tuple(map(to_tuple, data))
        else:
            return data

    def fill(data, length):
        length_diff = length - len(data)
        if isinstance(data[0], tuple):
            median = tuple(map(np.median, zip(*data)))
        else:
            median = np.median(data)
        return data + length_diff * (median,)

    t1 = to_tuple(t1)
    t2 = to_tuple(t2)

    max_length = max(len(t1), len(t2))
    t1 = fill(t1, max_length)
    t2 = fill(t2, max_length)

    def calculate_divergence(t1, t2):
        if isinstance(t1[0], tuple):
            return tuple(map(calculate_divergence, t1, t2))
        else:
            numeric_t1 = np.array([x if np.isreal(x) else np.mean(t1) for x in t1])
            numeric_t2 = np.array([x if np.isreal(x) else np.mean(t2) for x in t2])
            res = np.where(numeric_t2 <= numeric_t1, numeric_t1 - numeric_t2, np.nan)
            return tuple(res)

    divergence = calculate_divergence(t1, t2)
    return divergence
```

