    isbn = isbn.replace("-", "").replace(" ", "")  # remove hyphens and spaces
    if len(isbn) != 10:
        return False

    checksum = 0
    for i in range(9):
        if not isbn[i].isdigit():
            return False
        checksum += int(isbn[i]) * (10 - i)

    last_char = isbn[-1]
    if not last_char.isdigit() and last_char != 'X':
        return False
    checksum += 10 if last_char == 'X' else int(last_char)

    return checksum % 11 == 0


def validate_isbn_13(isbn):
    isbn = isbn.replace("-", "").replace(" ", "")  # remove hyphens and spaces
    if len(isbn) != 13:
        return False

    if not isbn.isdigit():
        return False

    checksum = 0
    for i in range(0, 12, 2):
        checksum += int(isbn[i])
    for i in range(1, 12, 2):
        checksum += int(isbn[i]) * 3

    return checksum % 10 == 0


def validate_registration_group(isbn):
    isbn = isbn.replace("-", "").replace(" ", "")  # remove hyphens and spaces
    if len(isbn) != 10 and len(isbn) != 13:
        return False

    if isbn[0] == '0':
